const toRad = d => d * Math.PI / 180;

// Current location (San Francisco area)
const lat1 = 37.7749, lon1 = -122.4194;

// Boston, MA 02118 (South End neighborhood) approximate coordinates
const lat2 = 42.3388, lon2 = -71.0726;

// Haversine formula
const R_km = 6371;
const R_mi = 3958.8;

const dLat = toRad(lat2 - lat1);
const dLon = toRad(lon2 - lon1);
const a = Math.sin(dLat/2)**2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon/2)**2;
const c = 2 * Math.asin(Math.sqrt(a));

const dist_km = R_km * c;
const dist_mi = R_mi * c;

console.log('From:  San Francisco, CA (37.7749, -122.4194)');
console.log('To:    Boston, MA 02118  (42.3388, -71.0726)');
console.log('');
console.log('Great-circle (straight-line) distance:');
console.log('  ' + dist_km.toFixed(1) + ' km');
console.log('  ' + dist_mi.toFixed(1) + ' miles');
"
